     try{ if(G){ G.bagOpen=false; G.giftIn=null; G.giftOut=null; } }catch(_g){}
     try{ __endRaid('abandon'); __topClear(); }catch(_c){}
   }
   return bad.length?bad.join('; '):null; }},
